// quantum_posture: imported workstation receipts use classical Ed25519 signatures.
package workstation

import (
	"crypto/ed25519"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"strings"

	"github.com/Mindburn-Labs/helm-ai-kernel/core/pkg/canonicalize"
	"github.com/Mindburn-Labs/helm-ai-kernel/core/pkg/contracts"
)

// retiredObserveOnlySignerKeyID identifies the public key generated by the
// removed source-derived v0.7.2 signer. It is permanently rejected as a
// trust anchor because anyone can reproduce its private key from old source.
const retiredObserveOnlySignerKeyID = "ed25519:c139f35d7f54e90525423dde5e57b3d8ab77c05a18155466936755b447a77c68"

func signReceipt(receipt *contracts.AgentRunReceipt, seed []byte) error {
	if len(seed) == 0 {
		return errors.New("signing seed is required")
	}
	if len(seed) != ed25519.SeedSize {
		return fmt.Errorf("signing seed must be %d bytes", ed25519.SeedSize)
	}
	priv := ed25519.NewKeyFromSeed(seed)
	pub := priv.Public().(ed25519.PublicKey)
	receipt.SignerKeyID = ed25519SignerKeyID(pub)
	receipt.Signature = ""
	receipt.ReceiptHash = ""
	canonical, err := canonicalize.JCS(receipt)
	if err != nil {
		return fmt.Errorf("canonicalize agent run receipt: %w", err)
	}
	hash := sha256.Sum256(canonical)
	receipt.ReceiptHash = hex.EncodeToString(hash[:])
	receipt.Signature = hex.EncodeToString(ed25519.Sign(priv, canonical))
	return nil
}

// VerifyReceiptSignature checks receipt integrity against the public key embedded
// in the receipt itself. It does not establish signer trust. Call
// VerifyReceiptWithTrustedKey when a caller-owned trust anchor is available.
func VerifyReceiptSignature(receipt *contracts.AgentRunReceipt) (bool, error) {
	if receipt == nil {
		return false, errors.New("receipt is nil")
	}
	keyHex := strings.TrimPrefix(receipt.SignerKeyID, "ed25519:")
	pub, err := hex.DecodeString(keyHex)
	if err != nil {
		return false, fmt.Errorf("decode signer key: %w", err)
	}
	if len(pub) != ed25519.PublicKeySize {
		return false, fmt.Errorf("signer key must be %d bytes", ed25519.PublicKeySize)
	}
	sig, err := hex.DecodeString(receipt.Signature)
	if err != nil {
		return false, fmt.Errorf("decode signature: %w", err)
	}
	copyReceipt := *receipt
	copyReceipt.Signature = ""
	copyReceipt.ReceiptHash = ""
	canonical, err := canonicalize.JCS(&copyReceipt)
	if err != nil {
		return false, fmt.Errorf("canonicalize receipt: %w", err)
	}
	hash := sha256.Sum256(canonical)
	if hex.EncodeToString(hash[:]) != receipt.ReceiptHash {
		return false, nil
	}
	return ed25519.Verify(ed25519.PublicKey(pub), canonical, sig), nil
}

// VerifyReceiptWithTrustedKey verifies receipt integrity only when its declared
// signer matches the caller-owned trusted public key.
func VerifyReceiptWithTrustedKey(receipt *contracts.AgentRunReceipt, trusted ed25519.PublicKey) (bool, error) {
	if receipt == nil {
		return false, errors.New("receipt is nil")
	}
	if len(trusted) != ed25519.PublicKeySize {
		return false, fmt.Errorf("trusted signer key must be %d bytes", ed25519.PublicKeySize)
	}
	if receipt.SignerKeyID != ed25519SignerKeyID(trusted) {
		return false, nil
	}
	if receipt.SignerKeyID == retiredObserveOnlySignerKeyID {
		return false, nil
	}
	return VerifyReceiptSignature(receipt)
}

func ed25519SignerKeyID(publicKey ed25519.PublicKey) string {
	return "ed25519:" + hex.EncodeToString(publicKey)
}
